// One OTel setup emits all three pillars from a service.
func setupObservability(ctx context.Context) (func(context.Context) error, error) {
	// Traces: batch spans to an OTLP collector (Jaeger/Tempo).
	tp, err := newTracerProvider(ctx)
	if err != nil {
		return nil, err
	}
	otel.SetTracerProvider(tp)
	// Propagator so trace context crosses HTTP/gRPC boundaries.
	otel.SetTextMapPropagator(propagation.TraceContext{})
	// Metrics + structured logs are wired separately (Prometheus, slog).
	return tp.Shutdown, nil // flush spans on shutdown
}

var tracer = otel.Tracer("orders")

// fetchOrder creates a child span so the DB call shows up in the waterfall.
func fetchOrder(ctx context.Context, id string) (*Order, error) {
	ctx, span := tracer.Start(ctx, "fetchOrder",
		trace.WithAttributes(attribute.String("order.id", id)))
	defer span.End() // records duration when the func returns

	o, err := db.QueryOrder(ctx, id)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, "query failed") // marks the span red
		return nil, err
	}
	return o, nil
}

// Client: otelhttp.Transport injects traceparent into outbound requests.
client := &http.Client{Transport: otelhttp.NewTransport(http.DefaultTransport)}

// Server: otelhttp.NewHandler extracts traceparent and starts a server span.
func main() {
	mux := http.NewServeMux()
	mux.Handle("/orders/{id}", http.HandlerFunc(ordersHandler))
	// Every incoming request now continues the caller's trace.
	handler := otelhttp.NewHandler(mux, "orders-service")
	_ = http.ListenAndServe(":8080", handler) // context is propagated for us
}

// loggerFrom returns a slog.Logger tagged with the current trace ID.
func loggerFrom(ctx context.Context, base *slog.Logger) *slog.Logger {
	sc := trace.SpanContextFromContext(ctx)
	if !sc.HasTraceID() {
		return base // no active span; log without correlation
	}
	return base.With(
		slog.String("trace_id", sc.TraceID().String()),
		slog.String("span_id", sc.SpanID().String()),
	)
}

func handle(ctx context.Context, base *slog.Logger) {
	log := loggerFrom(ctx, base)
	log.InfoContext(ctx, "processing order") // includes trace_id=... span_id=...
}

// A JSON slog logger with request-scoped fields set once.
func newLogger() *slog.Logger {
	return slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{
		Level: slog.LevelInfo,
	}))
}

func requestLogger(base *slog.Logger, r *http.Request) *slog.Logger {
	// Attach fields once; every subsequent line inherits them.
	return base.With(
		slog.String("route", r.Pattern),
		slog.String("method", r.Method),
	)
}

// A RED-style histogram: one metric captures rate, errors, and duration.
var reqDur = promauto.NewHistogramVec(prometheus.HistogramOpts{
	Name:    "http_request_duration_seconds",
	Buckets: prometheus.DefBuckets, // for latency SLOs / p99
}, []string{"route", "method", "status"}) // status label -> error rate

func observe(route, method string, status int, start time.Time) {
	reqDur.WithLabelValues(route, method, strconv.Itoa(status)).
		Observe(time.Since(start).Seconds()) // Rate=count, Errors=status>=500, Duration=histogram
}

