package main

import (
	"context"
	"log/slog"
	"net/http"
	"os"
	"time"

	"go.opentelemetry.io/contrib/instrumentation/net/http/otelhttp"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"
)

var (
	tracer = otel.Tracer("orders")
	base   = slog.New(slog.NewJSONHandler(os.Stdout, nil))
)

// loggerFrom tags the logger with the active trace/span IDs.
func loggerFrom(ctx context.Context) *slog.Logger {
	sc := trace.SpanContextFromContext(ctx)
	if !sc.HasTraceID() {
		return base
	}
	return base.With(
		slog.String("trace_id", sc.TraceID().String()),
		slog.String("span_id", sc.SpanID().String()),
	)
}

func ordersHandler(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context() // already carries the server span from otelhttp
	log := loggerFrom(ctx)

	// Child span for the DB step shows as a segment in the waterfall.
	ctx, span := tracer.Start(ctx, "loadOrder",
		trace.WithAttributes(attribute.String("order.id", r.PathValue("id"))))
	time.Sleep(20 * time.Millisecond) // simulated DB call
	span.End()

	log.InfoContext(ctx, "order loaded") // line carries trace_id + span_id
	_, _ = w.Write([]byte("ok"))
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /orders/{id}", ordersHandler)
	// Wrap once: extract traceparent, start a server span per request.
	handler := otelhttp.NewHandler(mux, "orders-service")
	_ = http.ListenAndServe(":8080", handler)
}

