package main

import (
	"context"
	"io"
	"net/http"

	"go.opentelemetry.io/contrib/instrumentation/net/http/otelhttp"
	"go.opentelemetry.io/otel"
)

var tracer = otel.Tracer("gateway")

// callInventory makes a downstream call that stays in the same trace.
func callInventory(ctx context.Context, sku string) (string, error) {
	ctx, span := tracer.Start(ctx, "callInventory")
	defer span.End()

	// Transport injects traceparent from ctx into the outbound request.
	client := &http.Client{Transport: otelhttp.NewTransport(http.DefaultTransport)}

	// NewRequestWithContext is REQUIRED: the ctx carries the span to inject.
	req, err := http.NewRequestWithContext(ctx, http.MethodGet,
		"http://inventory:8080/stock/"+sku, nil)
	if err != nil {
		return "", err
	}

	resp, err := client.Do(req) // traceparent header sent automatically
	if err != nil {
		span.RecordError(err)
		return "", err
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	return string(body), err
}

package main

import (
	"net/http"
	"strconv"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promauto"
)

// One histogram gives Rate (count), Errors (status label), Duration (buckets).
var reqDur = promauto.NewHistogramVec(prometheus.HistogramOpts{
	Name:    "http_request_duration_seconds",
	Buckets: prometheus.DefBuckets,
}, []string{"route", "method", "status"})

type statusRecorder struct {
	http.ResponseWriter
	status int
}

func (s *statusRecorder) WriteHeader(code int) {
	s.status = code // capture before delegating
	s.ResponseWriter.WriteHeader(code)
}

// REDMetrics records the RED signals for every request.
func REDMetrics(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rec := &statusRecorder{ResponseWriter: w, status: http.StatusOK}
		start := time.Now()
		next.ServeHTTP(rec, r)
		reqDur.WithLabelValues(
			r.Pattern, r.Method, strconv.Itoa(rec.status),
		).Observe(time.Since(start).Seconds()) // one Observe = all three RED signals
	})
}

