package solution

import (
	"context"
	"log/slog"

	"go.opentelemetry.io/otel/trace"
)

// TraceHandler wraps an slog.Handler and stamps trace_id onto every record.
type TraceHandler struct {
	slog.Handler // embeds inner: promotes Enabled/WithAttrs/WithGroup
}

// Handle adds trace_id (and span_id) from ctx when a span is active.
func (h TraceHandler) Handle(ctx context.Context, r slog.Record) error {
	sc := trace.SpanContextFromContext(ctx)
	if sc.HasTraceID() {
		// AddAttrs mutates the record's own attr slice, not the caller's.
		r.AddAttrs(
			slog.String("trace_id", sc.TraceID().String()),
			slog.String("span_id", sc.SpanID().String()),
		)
	}
	return h.Handler.Handle(ctx, r) // delegate to the inner handler
}

