package solution

import (
	"bytes"
	"context"
	"encoding/hex"
	"log/slog"
	"strings"
	"testing"

	"go.opentelemetry.io/otel/trace"
)

func TestTraceHandlerInjectsID(t *testing.T) {
	var buf bytes.Buffer
	h := TraceHandler{Handler: slog.NewJSONHandler(&buf, nil)}
	log := slog.New(h)

	tid, _ := trace.TraceIDFromHex("4bf92f3577b34da6a3ce929d0e0e4736")
	sid, _ := trace.SpanIDFromHex("00f067aa0ba902b7")
	sc := trace.NewSpanContext(trace.SpanContextConfig{TraceID: tid, SpanID: sid})
	ctx := trace.ContextWithSpanContext(context.Background(), sc)

	log.InfoContext(ctx, "hello")
	if !strings.Contains(buf.String(), "4bf92f3577b34da6a3ce929d0e0e4736") {
		t.Fatalf("trace_id not injected: %s", buf.String())
	}

	buf.Reset()
	log.InfoContext(context.Background(), "no span") // no trace id
	if strings.Contains(buf.String(), "trace_id") {
		t.Fatalf("unexpected trace_id when no span: %s", buf.String())
	}
	_ = hex.EncodeToString(nil)
}

