func TestREDMetricsObserves(t *testing.T) {
	reqDur := prometheus.NewHistogramVec(prometheus.HistogramOpts{
		Name:    "http_request_duration_seconds",
		Buckets: prometheus.DefBuckets,
	}, []string{"route", "method", "status"})

	mux := http.NewServeMux()
	mux.HandleFunc("GET /ping", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusInternalServerError)
	})
	h := REDMetrics(reqDur)(mux)

	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, httptest.NewRequest("GET", "/ping", nil))

	n := testutil.CollectAndCount(reqDur)
	if n == 0 {
		t.Fatalf("expected at least one observed series, got %d", n)
	}
	if rr.Code != http.StatusInternalServerError {
		t.Fatalf("status not propagated: %d", rr.Code)
	}
}

