func handler(w http.ResponseWriter, r *http.Request) {
	reqCtx := r.Context() // holds the parent server span

	// Carry the trace context but detach the cancellation/deadline so the
	// background work survives the handler returning.
	bgCtx := context.WithoutCancel(reqCtx) // Go 1.21+: keeps values, drops cancel

	go func() {
		// Starts as a CHILD of the request's span -> same trace ID.
		ctx, span := tracer.Start(bgCtx, "auditWrite")
		defer span.End()
		writeAudit(ctx)
	}()

	_, span := tracer.Start(reqCtx, "respond")
	defer span.End()
	_, _ = w.Write([]byte("ok"))
}

func LogWithTrace(ctx context.Context, base *slog.Logger) *slog.Logger {
	sc := trace.SpanContextFromContext(ctx) // read active span context
	if !sc.HasTraceID() {
		return base // no active span -> no correlation fields
	}
	return base.With(
		slog.String("trace_id", sc.TraceID().String()),
		slog.String("span_id", sc.SpanID().String()),
	) // child logger carries the IDs on every line
}
